scripts.factorial_modulo:
def solve(inputs: dict) -> float:
    n = int(inputs['N'])
    mod = int(inputs['MOD'])

    # Compute n! modulo mod
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

